La gestion d'erreurs suit des patterns stricts pour éviter les catch vides et garantir la robustesse :

## 1. Interdit : Catch Vide

**Jamais de catch générique silencieux :**
```python
# ❌ ABSOLUMENT INTERDIT
try:
    process_video(video_path)
except:
    pass  # Cache toutes les erreurs

# ❌ AUSSI INTERDIT
try:
    api_call()
except Exception:
    pass  # Ignore silencieusement
```

## 2. Exceptions Spécifiques

**Définir des exceptions métier :**
```python
# config/exceptions.py
class WorkflowError(Exception):
    """Erreur de base du workflow."""
    pass

class StepValidationError(WorkflowError):
    """Étape invalide ou mal configurée."""
    pass

class VideoProcessingError(WorkflowError):
    """Erreur de traitement vidéo."""
    pass

class SecurityError(WorkflowError):
    """Violation de sécurité."""
    pass
```

## 3. Pattern de Gestion d'Erreurs

**Gestion structurée par couche :**
```python
# Dans les services (couche métier)
def process_video_secure(video_path: str) -> bool:
    """Traite une vidéo avec gestion d'erreurs complète."""
    try:
        # Validation préalable
        if not os.path.exists(video_path):
            raise FileNotFoundError(f"Vidéo introuvable: {video_path}")

        # Traitement
        result = self._convert_video(video_path)
        return result.success

    except FileNotFoundError as e:
        logger.error(f"Fichier vidéo manquant: {e}")
        raise VideoProcessingError(f"Vidéo inaccessible: {video_path}") from e

    except subprocess.CalledProcessError as e:
        logger.error(f"FFmpeg échoué pour {video_path}: {e.stderr}")
        raise VideoProcessingError(f"Conversion échouée: {video_path}") from e

    except Exception as e:
        logger.critical(f"Erreur inattendue traitement {video_path}: {e}")
        raise VideoProcessingError(f"Erreur système: {video_path}") from e
```

## 4. Gestion dans les Routes Flask

**Routes comme wrappers légers :**
```python
# routes/api_routes.py
@api_bp.route('/api/step/<step_key>/run')
@measure_api('run_step')
def run_step(step_key: str):
    """Lance une étape avec gestion d'erreurs HTTP."""
    try:
        # Validation d'entrée
        if not step_key or step_key not in VALID_STEPS:
            return jsonify({'error': 'Étape invalide'}), 400

        # Appel service
        result = workflow_service.run_step(step_key)
        return jsonify(result)

    except StepValidationError as e:
        logger.warning(f"Validation échouée pour {step_key}: {e}")
        return jsonify({'error': str(e)}), 400

    except WorkflowError as e:
        logger.error(f"Erreur workflow {step_key}: {e}")
        return jsonify({'error': 'Erreur de traitement'}), 500

    except Exception as e:
        logger.critical(f"Erreur inattendue {step_key}: {e}")
        return jsonify({'error': 'Erreur système'}), 500
```

## 5. Gestion d'Erreurs Frontend

**JavaScript avec try/catch structuré :**
```javascript
// static/utils/ErrorHandler.js
export class ErrorHandler {
  static handleApiError(error, context) {
    console.error(`Erreur API ${context}:`, error);

    if (error.response) {
      // Erreur HTTP
      const status = error.response.status;
      const message = error.response.data?.error || 'Erreur inconnue';

      switch (status) {
        case 400:
          return this.showValidationError(message);
        case 500:
          return this.showSystemError(message);
        default:
          return this.showGenericError(message);
      }
    } else if (error.request) {
      // Erreur réseau
      return this.showNetworkError();
    } else {
      // Erreur autre
      return this.showGenericError(error.message);
    }
  }
}
```

## 6. Logging d'Erreurs

**Logs informatifs pour debugging :**
```python
# Pattern de logging
try:
    risky_operation(data)
except ValueError as e:
    logger.warning(f"Données invalides reçues: {e} | Data: {data[:100]}...")
    raise
except Exception as e:
    logger.error(f"Opération échouée | Type: {type(e).__name__} | Args: {e.args}")
    raise
```

## 7. Récupération d'Erreurs

**Retry avec backoff pour erreurs temporaires :**
```python
@retry(stop=stop_after_attempt(3), 
       wait=wait_exponential(multiplier=1, min=4, max=10),
       retry=retry_if_exception_type(ConnectionError))
def download_model_with_retry(model_url: str) -> bytes:
    """Télécharge un modèle avec retry automatique."""
    response = requests.get(model_url, timeout=30)
    response.raise_for_status()
    return response.content
```

## 8. Tests d'Erreurs

**Tester les chemins d'erreur :**
```python
# tests/unit/test_workflow_service.py
def test_run_step_invalid_key_raises_error():
    """Test que run_step rejette les clés invalides."""
    service = WorkflowService(mock_state, mock_config)

    mock_config.validate_step_key.return_value = False

    with pytest.raises(StepValidationError, match="Étape invalide"):
        service.run_step("INVALID_STEP")
```

Ces patterns garantissent que les erreurs sont gérées de façon prévisible et debuggable.

La thread safety est garantie par WorkflowState et des patterns de concurrence stricts :

## 1. WorkflowState : Source de Vérité Unique

**Singleton thread-safe avec RLock :**
```python
# services/workflow_state.py
import threading
from typing import Dict, Any

class WorkflowState:
    _instance = None
    _lock = threading.Lock()

    def __new__(cls):
        if cls._instance is None:
            with cls._lock:
                if cls._instance is None:
                    cls._instance = super().__new__(cls)
        return cls._instance

    def __init__(self):
        if not hasattr(self, '_initialized'):
            self._state_lock = threading.RLock()  # Reentrant Lock
            self._state = {}
            self._processes = {}
            self._initialized = True

# Fonction globale pour accès
_workflow_state = None
def get_workflow_state() -> WorkflowState:
    global _workflow_state
    if _workflow_state is None:
        _workflow_state = WorkflowState()
    return _workflow_state
```

## 2. Méthodes Atomiques

**Toutes les opérations protégées par verrou :**
```python
class WorkflowState:
    def update_step_status(self, step_key: str, status: str):
        """Met à jour le statut d'une étape de façon atomique."""
        with self._state_lock:
            if step_key not in self._state:
                self._state[step_key] = {}
            self._state[step_key]['status'] = status
            self._state[step_key]['updated_at'] = datetime.now()

    def get_step_info(self, step_key: str) -> Dict[str, Any]:
        """Récupère info étape de façon thread-safe."""
        with self._state_lock:
            return self._state.get(step_key, {}).copy()  # Copie défensive
```

## 3. Context Managers pour Séquences

**Protection des opérations longues :**
```python
class WorkflowState:
    @contextmanager
    def step_context(self, step_key: str):
        """Context manager pour opérations sur une étape."""
        with self._state_lock:
            self.update_step_status(step_key, 'running')
            self._processes[step_key] = multiprocessing.current_process()

        try:
            yield
        except Exception as e:
            with self._state_lock:
                self.update_step_status(step_key, 'error')
                self.append_step_log(step_key, f'ERROR: {e}')
            raise
        else:
            with self._state_lock:
                self.update_step_status(step_key, 'completed')
```

## 4. Interdit : Variables Globales

**Pas de state partagé en dehors de WorkflowState :**
```python
# ❌ ANCIEN PATTERN - DANGEREUX
PROCESS_INFO = {}
PROCESS_LOCK = threading.Lock()

def update_global_status(step_key, status):
    with PROCESS_LOCK:
        PROCESS_INFO[step_key] = status  # Race conditions possibles

# ✅ MODERNE - SÉCURISÉ
def update_step_status(step_key: str, status: str):
    ws = get_workflow_state()
    ws.update_step_status(step_key, status)  # Thread-safe garanti
```

## 5. PollingManager pour Frontend

**Mises à jour périodiques thread-safe :**
```python
// static/utils/PollingManager.js
class PollingManager {
  constructor() {
    this.isPolling = false;
    this.intervalId = null;
    this.lastUpdate = 0;
  }

  startPolling(callback, interval = 2000) {
    if (this.isPolling) return;

    this.isPolling = true;
    this.intervalId = setInterval(async () => {
      try {
        const data = await fetch('/api/state');
        const state = await data.json();
        callback(state);
        this.lastUpdate = Date.now();
      } catch (error) {
        console.error('Polling error:', error);
      }
    }, interval);
  }

  stopPolling() {
    if (this.intervalId) {
      clearInterval(this.intervalId);
      this.intervalId = null;
    }
    this.isPolling = false;
  }
}

export const pollingManager = new PollingManager();
```

## 6. Gestion des Processus Asynchrones

**Lancement thread-safe :**
```python
# services/workflow_service.py
def run_step_async(self, step_key: str) -> Dict[str, str]:
    """Lance une étape en arrière-plan de façon thread-safe."""
    ws = get_workflow_state()

    # Vérifications atomiques
    with ws._state_lock:
        if ws.is_sequence_running():
            return {'status': 'error', 'message': 'Séquence en cours'}

        if ws.is_step_running(step_key):
            return {'status': 'error', 'message': 'Étape déjà en cours'}

    # Lancement thread
    thread = threading.Thread(
        target=self._execute_step_thread,
        args=(step_key,),
        daemon=True
    )
    thread.start()

    return {'status': 'initiated'}
```

## 7. Tests Thread-Safe

**Vérification de la concurrence :**
```python
# tests/integration/test_concurrency.py
import threading
import time

def test_concurrent_step_updates():
    """Test mises à jour concurrentes."""
    ws = get_workflow_state()
    results = []

    def worker(thread_id):
        for i in range(10):
            ws.update_step_status('STEP1', f'thread_{thread_id}_{i}')
            time.sleep(0.01)  # Simuler travail
        results.append(f'thread_{thread_id}_done')

    # Lancer 5 threads
    threads = []
    for i in range(5):
        t = threading.Thread(target=worker, args=(i,))
        threads.append(t)
        t.start()

    for t in threads:
        t.join()

    assert len(results) == 5
    # Vérifier pas de corruption de state
```

Ces patterns garantissent que l'état reste cohérent même avec des accès concurrents.
